-- Rifts World Book 21: Splynn Dimensional Market - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 3 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~374-splynn-npcs-a.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('water-merchant', 'The Water Merchant', 'Unknown; even Lord Splynncryth knows him only as the Water Merchant', 'Proprietor of the Water Merchant shop, Splynn', 'rifts', 'Unknown; appears to be a sub-demon of some sort (as printed)', '12th level merchant/scholar (as printed)', 12, 'Anarchist', NULL, '5 feet, 6 inches (1.7 m)', NULL, '{"IQ":17,"ME":16,"MA":24,"PS":10,"PP":12,"PE":12,"PB":6,"Spd":15}', NULL, NULL, 153, NULL, 55, NULL, 10, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived.', NULL, 'No skill list is printed. He knows all lore of magic, ley lines, Faerie Folk, creatures of magic and demons.', 'Sees in the dark to 200 feet (61 m), can see the invisible, and regrows 2D6 M.D.C. every hour.', 'None. He knows all lore about magic, ley lines, Faerie Folk, creatures of magic and demons, and employs Herbalists, Druids and low level mages.', 'All Sensitive powers; I.S.P. 55. Counted as a Major Psionic.', NULL, NULL, 'None printed.', NULL, 'Strictly honest whenever he does business, whatever his alignment. Courteous and a little theatrical with customers, he sizes up visitors as adventurers before he pitches them a job.', NULL, NULL, 'An old-looking, gray-skinned, wrinkled being who keeps his body hidden under heavy robes, leaving only his bald head and hands bare. His Splynn shop sells enchanted waters gathered across Rifts Earth and beyond, herbal teas and remedies, wines and other drinks; a staff of Herbalists and Druids keeps it stocked, and he alone supplies the P.P.E.-charged water called Magic in a Vial, rationed to two per buyer. He wants water from a legendary healing well at Chichen Itza in the Yucatan, guarded by vampires, and will buy it but will not bankroll the trip.', 'Rifts World Book 21: Splynn Dimensional Market p.20-21'),
('old-west', 'Old West', NULL, 'Owner of the Antique Weapons Store, Splynn', 'rifts', 'Sowki', '8th level Ley Line Walker and 3rd level Gunslinger (as printed)', 8, 'Miscreant', NULL, NULL, NULL, '{"IQ":20,"ME":20,"MA":24,"PS":32,"PP":16,"PE":15,"PB":4,"Spd":14}', NULL, NULL, 140, 92, 30, NULL, 14, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived.', NULL, 'No skill list is printed. His race is not on a Race line: the shop text and his Natural Abilities name him a Sowki.', 'Has every Sowki ability, among them sight sharp enough to pick out a rabbit two miles (3.2 km) off, nightvision to 600 feet (183 m), seeing the invisible, and a magical command of every language.', 'All illusionary, concealment and metamorphosis magic, and all speed oriented spells. P.P.E. 92.', 'Mind Block, Sense Magic, Speed Reading, Summon Inner Strength, Total Recall, Object Read (Psychometry) and Hypnotic Suggestion; I.S.P. 30. Object Read is printed as object read.', NULL, NULL, 'Two genuine pre-Rifts revolvers of the American Old West, worn in fine leather holsters; several Techno-Wizard revolvers kept close; and an invisible magic sword from the Palladium World (5D6 M.D., see attacks).', NULL, 'Cunning and manipulative like his kind, but where most Sowki hide behind a false face he plays the drawling frontier gunfighter in dress, speech and manner, and that act is itself his mask. As a harmless-seeming shopkeeper he wins trust easily and trades in favours.', 'A network of mercenaries, warriors and assassins built on special deals and favours; he sometimes acts as their agent and go-between. He can book passage on Horune pirate ships.', NULL, 'A Sowki in full gunslinger costume who runs the Antique Weapons Store in Splynn: black powder pistols, Old West revolvers, bows, ancient melee and alien weapons sold to collectors, plus Techno-Wizard replica six-shooters and rifles, Wormwood black powder arms, minor Palladium World magic weapons, plundered pre-Rifts energy weapons and the odd Glitter Boy. He pays well for ancient Samurai swords from Japan and can arrange the voyage there aboard a Horune pirate ship.', 'Rifts World Book 21: Splynn Dimensional Market p.21-23'),
('rassa', 'Rassa', NULL, 'Owner and operator of the Feline Cages, Splynn', 'rifts', 'Raksasha; printed as Greater Demon of immense power and cunning', 'Equal to a 3rd level Wizard and an 8th level psychic (as printed)', 8, 'Diabolic', NULL, NULL, NULL, '{"IQ":20,"ME":19,"MA":21,"PS":30,"PP":18,"PE":23,"PB":11,"Spd":30}', NULL, NULL, 4500, 900, 130, NULL, 14, NULL, 'The block prints no attacks per melee and no combat bonuses; none is stored or derived. Level 8 is the higher of his two printed levels.', NULL, 'No skill list is printed. Natural disguise 96% with exposure to the subject.', 'Has every Raksasha ability: nightvision to 120 feet (27.4 m, as printed), sees the invisible, tracks by scent at 45%, teleports himself and up to 300 lbs (122 kg, as printed) as far as five miles (8 km), Dimensional Teleport 51%, Bio-Regenerates 4D6 M.D. each minute, resists fire and cold, and knows all languages by magic. Above all he can take the shape of any living creature, or become mist, and disguises himself at 96% once he has been exposed to the subject.', 'All metamorphosis, illusionary and protective spells, plus other conventional Wizard spells of level five or lower. P.P.E. 900.', 'All Healing, Sensitive and Physical powers, plus Psi-Sword (shaped as a scimitar), Psi-Shield, P.P.E. Shield, Mind Block Auto-Defense, Mentally Possess Others, Hypnotic Suggestion, Bio-Manipulation (the evil eye), Empathic Transmission, Hydrokinesis and Telekinetic Force Field; I.S.P. 130. A Master Psychic, as all Raksashas are. Bio-Manipulation is printed without its catalog suffix.', NULL, NULL, 'A cane topped with a cat emblem that is in truth a Greater Rune Weapon, with all the standard Rune Weapon abilities (its damage is not printed). Four times in 24 hours it commands felines: 1D4x10 animal-level cats or a single intelligent one at once; an intelligent target saves vs magic on 14 or higher, an animal on 18 or higher.', NULL, 'A smooth haggler and a sly manipulator who rarely lets a customer leave without a cat. He gambles, and would happily strip-mine a whole nation of cat people for profit.', 'Professional assassins, thieves and slavers.', 'He covets Omagua, the hidden nation of psionic mutant cats in South America, and the Divine Felines who lead it, and pays for intelligence on them or for their removal.', 'A Raksasha demon whose true shape is a muscular tiger-headed humanoid, though in Splynn he wears the guise of a big, yellow-furred, boar-like humanoid. He runs the Feline Cages, a small slave market for every kind of cat-like creature from house cats and big cats to Gryphons, Chimera and humanoid felines, prized for the quality of its stock.', 'Rifts World Book 21: Splynn Dimensional Market p.23-25');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'old-west', 'Invisible magic sword', '5D6 M.D.', 1, NULL, 'A Palladium World sword that is magically invisible.', 0);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('water-merchant', 'old-west', 'rassa');
SELECT 'and the notables 1' AS assertion, count(*) AS got, 1 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('water-merchant', 'old-west', 'rassa');

